function speechRegion() {
    var region = String(source.getLoginInfoMap().get('Region') || '').trim().toLowerCase();
    if (!/^[a-z][a-z0-9]*$/.test(region)) throw new Error('请填写 Azure 区域标识，例如 eastasia');
    return region;
}
function speechBody() {
    var text = java.get('speakText').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/searchKey/g, 'search&#75;ey');
    var percent = (Number(java.get('speakSpeed')) - 10) * 10;
    var rate = (percent >= 0 ? '+' : '') + percent + '%';
    return "<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='zh-CN'><voice name='zh-CN-YunjianNeural'><prosody rate='" + rate + "'>" + text + "</prosody></voice></speak>";
}
